      'title' => 'CEO MESSAGE',
      'slug' => 'ceo-message-4114',
      'excerpt' => '',
      'body' => '
Since it\'s establishment, BARQAAB has come a long way to become an epitome of excellence in the field of engineering consultancy. Over these years, the Company undertook 168 projects costing in excess of Rs.800 Billion. The fundamental principle in the implementation of these projects always remained the pursuit of excellence through hard work and honesty.

&nbsp;

At BARQAAB, we feel proud of the incomparable expertise and competence of a dedicated team of 450 professionals. Meeting the expectations of our clients and justifying their trust remains the hallmark of our business strategy.

&nbsp;

The Company plans to expand its business overseas. We have already signed an MOU with Mohammad Alshehhi Power L.L.C. Dubai to jointly undertake foreign and local projects. It is our expectation that the Company will continue to grow, both in the qualitative and quantitative aspects of its business. May Allah help us in this endeavor. Ameen.

&nbsp;

<strong>Engr. Ahmad Khan Bhatti</strong>
Chief Executive Officer



