      'title' => 'MANGLA DAM RAISING PROJECT ??? DETAILED ENGINEERING DESIGN',
      'slug' => 'mangla-dam-raising-project-detailed-engineering-design-4143',
      'excerpt' => '',
      'body' => '
<h1 class="giga">MANGLA DAM RAISING <h1><h2 span class="accent">DETAILED ENGINEERING DESIGN, TENDER DOCUMENTATION AND CONSTRUCTION SUPERVISION</span></h2>


<img class="alignnone size-full wp-image-3983" src="http://www.barqaab.com/mainwebsite/img/slider2.jpg" alt="Mangla Dam" width="1100" />


<p style="text-align: left;">BARQAAB is providing technical expert services in the Project for the detailed engineering and tender documents in Phase-II, provide experts in bidding and award of construction contacts in phase-III A and also conduct construction supervision in phase-III B. BARQAAB Share is 17%.The Mangla Dam Raising Project involves raising of main and auxiliary dams, modification of the Headwork & orifice of the main spillway and construction of a control weir for the emergency spillway. Mangla Dam is to regain the storage capacity lost due to sedimentation in the reservoir.  The average annual water availability for irrigation releases will increase by 2.88 MAF.  To achieve other benefits like increase in annual energy output by 772 GWh which is equivalent to 150 MW in generating capacity, development of fisheries and increased economic in the area.</p>


<p style="padding:50px 0px 50px 0px; border-style: dashed; border-width: 1px; font-weight:bold;">Total Project Cost: PKR 62,500 Million.
BARQAAB Share: 33%.
Date of Commencement: August 2002.
Date of Completion: December 2010.</p>
',
