      'title' => 'REVIEW AND UPGRADATION OF PRELIMINARY FEASIBILITY STUDY OF BASHA DIAMER DAM PROJECT.',
      'slug' => 'review-and-upgradation-of-preliminary-feasibility-study-of-basha-diamer-dam-project-4144',
      'excerpt' => '',
      'body' => '
<h1 class="giga">BASHA DIAMER DAM PROJECT </h1><h3>REVIEW AND UPGRADATION OF PRELIMINARY FEASIBILITY STUDY</h3>


<img class="alignnone size-full wp-image-3983" src="https://barqaab.com.pk////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////wp-content/uploads/2014/11/slider1.jpg" alt="Mangla Dam" width="1100" />


<p style="text-align: left;">Project layout for the different types of dam was developed selecting the type of Dam. Optimization studies for each alternative considered taking into account. Preparation of feasibility level designs of all structures for the selected, alternative including general layout. Economic analysis, costing and preparation of PC-1 of the Project including telecom and SCADA system. Basha Dam proposed site is located near Chillas on river Indus and shall have a live storage capacity of 7.34 MAF.  It shall have a power potential of 4500 MW.  This project is a part of WAPDA???s Vision 2025 Programme and aims at enhancing the irrigation and power availability of the country.  This dam is located in a highly seismic zone and is extremely high and involves relocation and upgradation of KKH which gets submerged for 130-Km length.  The Consultants have been selected by WAPDA to upgrade the feasibility and carry out various investigations required for the Project.</p>


<p style="padding:50px 0px 50px 0px; border-style: dashed; border-width: 1px; font-weight:bold;">Total Project Cost: PKR 6.4 Billion.
BARQAAB Share: 33%.
