      'title' => '84 MW GORKIN-MATILTAN HYDROPOWER PROJECT',
      'slug' => '84-mw-gorkin-matiltan-hydropower-project-4147',
      'excerpt' => '',
      'body' => '
<h1 class="giga">84 MW </span></h1><h1 class="giga">GORKIN-MATILTAN<span class="accent"> HYDROPOWER PROJECT</span></h1>


<img class="alignnone size-full wp-image-3983" src="https://barqaab.com.pk////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////wp-content/uploads/2014/11/matiltan.jpg" alt="Mangla Dam" width="1100" />


<p style="text-align: left;">The Government of Khyber Pakhtunkhwah (KPK) has decided to undertake implementation of 84 MW Matiltan Hydropower Project, district Swat through Sarhad Hydel Organization (PHYDO) as the Executing Agency.  BARQAAB in joint venture with two other local firms is providing Consultancy Services for the construction of 84 MW HPP. This consultancy agreement was signed on 17th April, 2012 between PHYDO and BARQAAB Consultancy Services, (PVT) Ltd Lahore.</p>
<h4 style="text-align: left;">Scope of Work</h4>
<p style="text-align: left;">BARQAAB is responsible for preparing Basic Design of the Project and Draft EPC Contract Documents based on FIDIC Conditions of Contract for EPC/Turnkey projects.  BARQAAB will monitor, review and supervise the EPC contractor engineering, procurement, contract administration and construction activities.</p>



<p style="padding:50px 0px 50px 0px; border-style: dashed; border-width: 1px; font-weight:bold;">Total Project Cost: PKR 15,800 Million.
BARQAAB Share: 60%.
Date of Commencement: May 2012.
Date of Completion: June 2016.</p>
',
