      'body' => '
<h1 class="giga">WINDER DAM<span class="accent"> PROJECT</span></h1>


<img class="alignnone size-full wp-image-3983" src="http://www.barqaab.com/mainwebsite/damhydroimages/dh3.jpg" alt="Mangla Dam" width="1100" />


<p style="text-align: left;">BARQAAB provided technical expert services in the study for Hydrology Water availability assessment of sedimentation, reservoir operation, structural design review, environmental and resettlement implications, preparation of EIA and RAP, geo-technical and seismic issues, construction issues and economic feasibility of the Project.  It also provided the home office coordination to the joint venture.  BARQAAB prepared Tender Documents on EPC basis and evaluated the Contractors Bids.The Feasibility Report has been prepared in fulfilment of the terms of the Consultancy Agreement. The report covers hydrology, geology & geotechnical, soil and agriculture, socio-economic, Environment and Engineering aspects of the project on feasibility level designs of the dam, spillway & other related structures in addition to economic & financial analysis.  The Tender Documents were prepared on EPC Basis.  The dam is proposed to irrigate an area of over 30,000 acres in Balochistan.</p>



<p style="padding:50px 0px 50px 0px; border-style: dashed; border-width: 1px; font-weight:bold;">Total Project Cost: PKR 8,700 Million.
Date of Commencement: June 2006.
Date of Completion: August 2007.</p>
',
