      'body' => '
<h1 class="giga">NAULONG DAM<span class="accent"> PROJECT</span></h1>


<p style="text-align: left;">Detailed Engineering Design and Tender Documents of Naulong Dam Project in Balochistan. <BR><BR>BARQAAB Provided major services in Design, Hydrology, Environment and Tender Document Preparation in this Project.<BR>Noulang Dam is located on Mula river in District Jhal MAgsi, Balochistan.  The dam is a Zone Earthfill with a gross storage capacity of 0.124 MAF.  The spillway having a capacity of 290,000 cusecs will be located on a valley.  Irrigation outlet will be located under the Auxiliary Dam.  The waterway will consist of 13 bays of 46 ft. width.  The Dam is 138 ft. High and 2,510 ft. long and shall irrigated about 25,337 acres. </p>



<p style="padding:50px 0px 50px 0px; border-style: dashed; border-width: 1px; font-weight:bold;">
Total Project Cost: PKR 7,800 Million.
