      'title' => '20 MW RASUL LOW HEAD HYDROPOWER PROJECT ??? FEASIBILITY STUDY',
      'slug' => '20-mw-rasul-low-head-hydropower-project-feasibility-study-4363',
      'excerpt' => '',
      'body' => '
<h1 class="giga">20MW RASUL LOW HEAD <BR> <span class="accent"> HYDROPOWER PROJECT</span></h1><h2>( Feasibilty Study)</h2>


<p style="text-align: left;">The Consultancy Services Include supervision of survey and investigation work conducted on the program prepared by Consultants and Carrying out Feasibility Study of the hydropower project and prepare an acceptable and bankable report of the project covering the Feasibility level Design and drawings of each structure, Bill of Quantities, Cost estimates, Powerhouse and Power plant, hydro mechanical, electrical and miscellaneous auxiliary equipment (Technical particulars, numbers, capacity etc.), Economic & Financial Analysis, Environmental Impact Assessment, Workout cost per KWh of power production, Prepare and provide the Hydrological, Geotechnical and Topographical Survey Report, Alternative Layouts & Comparison, IEE Social and Resettlement Report and Feasibility Report.</p>

<BR><p style="text-align: left;">The main objective of Rasul Low Head Hydropower Project is to utilize the flows of Rivers Jhelum at Rasul Barrage to generate 20 MW power and supply into national grid system immediately. The project, falling in the load centre area will be connected to the nearest grid station and thus will contribute to the national grid with minimum line losses and no substantial cost for transmission line.</p>

<BR><p style="text-align: left;">The Rasul Low Head Hydropower Project is proposed to be constructed along the right bank of Rasul Barrage on Jhelum River. The project area is located on the right bank of Rasul Barrage. The head race and the power house are at a distance of 275 m away from the right pocket of the Barrage. The power house is estimated to have an installed capacity of 20 MW and an annual energy output of 94 GWh at 29% probability time with available head ranging between 2.5 to 8.0 m. The power house including service bay has a length of 40 m and width of 82 m.  The total length including upstream and downstream concrete floors is 101.45 m. The designed foundation level is fixed at EL 201.55 whereas the top elevation of the powerhouse is at 235.35 m. The head race comprises trapezoidal cross-section having total length of approximately 557 m and a bed width of 95 m.  The top width is approximately 125.60 m and the average depth is about 3.5 m. The tail race comprising trapezoidal cross-section has a length of approximately 411 m and a bed width of 88 m.  The top width is approximately 135 m.</p>



<p style="padding:50px 0px 50px 0px; border-style: dashed; border-width: 1px; font-weight:bold;">
Date of Commencement: April 2008
Date of Completion: November 2008
',
