      'excerpt' => '',
      'body' => '
<h1 class="giga">PELAR DAM, AWARAN<span class="accent"> PROJECT</span></h1>



<p style="text-align: left;">Preparation of Updated Design / Main Report Design, Drawings, Specifications & Updated Pc-I Performa.</p>
<BR><p style="text-align: left;">The Consultants reviewed and update the feasibility study of Pelar Storage Dam Project. Updating of the feasibility study involves hydrological studies (water availability, sediment and flood studies), design aspects (structural, hydraulic, geotechnical and hydro-mechanical), hydropower potential, soil survey, agricultural study (cropping pattern, crop water requirements, yields and returns) EIA study, cost estimates (civil, electrical, mechanical works environmental mitigation, project engineering , management and contingencies), economic analysis, financial analysis and preparation of updated feasibility report.</p>
<p style="text-align: left;">A potential storage site is available on Nal River in District Awaran of Balochistan Province for the construction of a dam. A gravity Dam/Spillway approximately 40 meter (131.23 ft) high across Nal River will create a reservoir of about 122.33 MCM gross capacity and 57.96 MCM live storage. This will provide assured regulated supplies to the existing command area of about 25,650 acres downstream the Nal River. From water supply control structure, regulated flow will be conveyed to a main pipe line (73.5 Km) having 4.05 Cumecs capacity.</p>


<p style="padding:50px 0px 50px 0px; border-style: dashed; border-width: 1px; font-weight:bold;">Total Project Cost: PKR 4.6 Billion.
BARQAAB Share: 100%.
Date of Commencement: August 2009.
Date of Completion: April 2010.</p>
',
