      'title' => 'GHABIR DAM PROJECT',
      'slug' => 'ghabir-dam-project-4157',
      'excerpt' => '',
      'body' => '
<h1 class="giga">GHABIR DAM<span class="accent"> PROJECT</span></h1>
<p style="text-align: left;">Feasibility Study of Ghabir Dam Project in Punjab in association with PES.<BR><BR>The Ghabir Dam Project is owned by the Pakistan Water and Power Development Authority (WAPDA) and EPC/Turnkey based Contract which is to be constructed on confluence of Ghabir Nullah and Churri Nullah in the Punjab Province of Pakistan. As per requirement of the Client, A joint venture of NEIE-LAC in association with BARQAAB Consulting Services (Pvt.) Ltd. has carried out the design of the project. The previous data and investigations carried out by Consultants during the Feasibility Stage Study of the Project have been used to develop the basic design of the Project. However, the further investigations if considered necessary will be carried out and subsequently incorporated in the design during the later stages of the project.<BR><BR>
<p style="text-align: left;">Two different options viz. Concrete Face Rock-fill Dam (CFRD) and Embankment Dam were studied for the project site. On the basis of comparative studies, it was concluded that availability of construction materials, project economics and technical aspects favors the construction of Embankment Dam. A comprehensive basic design proposal is prepared and being submitted considering technical, economical and constructional aspects. However, this design may be changed/ modified after hydraulic model studies and any site related problems, when project is awarded to the contactor.</p>
&nbsp;
<p style="text-align: left;">Ghabir Dam Project has the following major components:</p>

<p><ul>
	<li style="text-align: left;">Earth core Rockfill dam</li>
	<li style="text-align: left;">Concrete spillway and stilling basin</li>
	<li style="text-align: left;">Outlet structure</li>
	<li style="text-align: left;">Irrigation system</li>
</ul></p>
',
