      'slug' => 'greater-thal-canal-project-4391',
      'excerpt' => '',
      'body' => '
<h1 class="giga">GREATER THAL CANAL<span class="accent"> PROJECT</span></h1>
<h2>DETAILED ENGINEERING STUDIES, TENDER DOCUMENTS AND CONSTRUCTION SUPERVISION</BR>





<p style="text-align: left;">BARQAAB provided technical expert services in the Project for Detailed Design of Canal, preparation of Detailed Design for Canal Command Network of distributaries & minors, design of drainage measures to minimize waterlogging and salinity problems arising from project implementation.  The Consultants would also design the E & M works on the canal and conduct Environmental Impact Assessment (EIA) and prepare Resettlement Action Plan (RAP).  The Consultants shall prepare Tender Drawings and documents for construction and carry out Construction of works.</p>
<BR><p style="text-align: left;">Greater Thal Canal Project (GTCP) is one of the priority projects under WAPDA???s Water Vision 2025 Program. It falls in the territory of Jhang, Khushab, Bhakkar and Layyah districts.  The Project comprises an irrigation system network transmitting 8,500 cusecs discharge to irrigate an area of about 1,918,000 acres of Thal Doab (the area between Indus and Jhelum rivers).  The Irrigation System consists of main Canal 22.5 miles, branch and sub-branch canal 223 miles and distributaries / minors 1,221 miles along with other allied structure, regular, falls, bridges etc.</p>


<p style="padding:50px 0px 50px 0px; border-style: dashed; border-width: 1px; font-weight:bold;">Total Project Cost: PKR 158,45 Million.
BARQAAB Share: 100%.
Date of Commencement: March 2002.
Date of Completion: December 2008.</p>
',
