      'type' => 'project',
      'category' => 'canals-barrages-drains',
      'title' => 'RASUL HYDEL POWER STATION',
      'slug' => 'rasul-hydel-power-station-4393',
      'excerpt' => '',
      'body' => '
<h1 class="giga">CONSTRUCTION OF SPILLWAY<span class="accent"> <BR>LINED CHANNEL AND APPURTENANT STRUCTURE ON SPILLWAY PROJECT</span></h1>
<h2>RASUL HYDEL POWER STATION</h2>


<img class="alignnone size-full wp-image-3983" src="https://barqaab.com.pk////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////wp-content/uploads/2014/11/canal5.jpg"/>


<p style="text-align: left;">BARQAAB provided technical expert services in the Project for preparation of tender documents, estimates and contract evaluation.  Construction Supervision of Syphonic Spillway, Lined Channel and related structures including falls, outfall structure and trash cleaning arrangements.</p>
<BR><p style="text-align: left;">The proposed Spillway Project at Rasul Hydel Power Station lies on the Right Bank of Rasul Power Channel (RPC) adjacent to Rasul Power Station.  It is about 11 KM north-east of Mandi Bahauddin and forms the central portion of the Chaj Doab lying between the Jhelum and Chenab rivers.</p>
<BR><p style="text-align: left;">The proposed Spillway Project at Rasul Hydel Power Station lies on the Right Bank of Rasul Power Channel (RPC) adjacent to Rasul Power Station.  It is about 11 KM north-east of Mandi Bahauddin and forms the central portion of the Chaj Doab lying between the Jhelum and Chenab rivers.</p>



<p style="padding:50px 0px 50px 0px; border-style: dashed; border-width: 1px; font-weight:bold;">Total Project Cost: PKR 93 Million.
