    6 => 
    array (
      'id' => 7,
      'wordpress_id' => 4048,
      'title' => 'ABOUT US',
      'slug' => 'barqaab',
      'excerpt' => NULL,
      'body' => '<a target="_blank" rel="noopener noreferrer nofollow" href="https://barqaab.com.pk////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////wp-content/uploads/2014/11/LOGO_BARQAAB_Monotone_black_450.png"><img src="https://barqaab.com.pk////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////wp-content/uploads/2016/12/bqb_logo_450.jpg" alt="BARQAAB" width="450" height="451"></a>BARQAAB has successfully implemented a large number of important projects independently and as a joint venture partner. BARQAAB is proud of independently planning, designing and supervising the construction of Rainee Canal Project including its Headwork of 10,000 cusecs at Guddu Barrage, 111km main/branch canal, 133km distributary and minor canals and 394 structures of various types. Hardly any other consultant has independently planned, designed and implemented a canal project of this size and nature. Other water sector projects include Muzaffargarh Canal Rehabilitation and Lining Project (as Lead Firm), Mangla Dam Raising Project and Khanki Barrage (as a major JV partner).BARQAAB also has the credit of being a major JV partner for the detailed design of Diamer Basha Dam Project ??? the highest roller compacted concrete dam in the world. BARQAAB independently carried out the feasibility of 10,000 cusecs Mangla-Marala Link Canal and the feasibility studies of a large number of dams in all the four provinces and in FATA. BARQAAB has recently completed feasibility study of Dadhocha Dam and is presently carrying out feasibility of UJC as a lead firm in the JV. BARQAAB was also associated as a JV partner for design of lining of Rice Canal, Dadu Canal, Rohri Canal, KB Feeder Canal, Phuleli Canal and Pinyari Canal in Sindh and is presently working as a JV partner for the construction supervision of Jhamrao Canal lining and rehabilitation project. BARQAAB was a JV partner for the detailed design and construction supervision of RBOD III project.<p>BARQAAB???s consultancy services cover all engineering disciplines but its main field of experience is the water and power resources development projects. Scope of services provided in these sectors cover planning including surveys, field investigations, project identification, concept papers, pre-feasibility and feasibility studies, ranking studies and prioritization, detailed design &amp; implementation of irrigation, drainage, dam and hydropower projects. BARQAAB also specializes in hydrogeological characteristics for groundwater management.</p>All BARQAAB Offices are ISO 9001:2015, 14001:2015 and 45001:2018 Certified.<h2></h2><h1>BARQAAB</h1><h6>Pursuing Excellence In Consultancy &amp; Advisory Services For Water &amp; Power Projects</h6>',
      'featured_image' => NULL,
      'status' => 'published',
      'sort_order' => 1,
