      'title' => '500kV GRID STATIONS AND TRANSMISSION LINES',
      'slug' => '500kv-grid-stations-and-transmission-lines',
      'category' => 'power-projects',
      'project_category_id' => 5,
      'subtitle' => '',
      'body' => '<h2 class="giga">500kV GIRD STATIONS AND TRANSMISSIONS</h2>
<p class="style11" style="text-align: left;"><strong>NTDC-KESC 500/220 kV INTERCONNECTION PROJECT (PHASE-I)</strong></p>
<p class="style11" style="text-align: left;">Preparation of Bid Level Design, Bill of Quantities, Technical Specifications, Tender Document and Evaluation of the Bids.</p>
<p class="style11" style="text-align: left;"><strong>Total Project Cost -</strong> PKR 284 Million and US$ 29.3 Million
<strong>Barqaab Share - </strong>100%
<strong>Date of Commencement - </strong>June 2003
<strong>Date of Completion - </strong>March 2004</p>
<p class="style11" style="text-align: left;"><strong>SCOPE OF WORK</strong></p>
<p class="style11" style="text-align: left;">Two Nos. 500/220kV 3x200MVA Transformer Bay.
Two Nos. 220kV Line Bays.
Two Nos. 500kV Line Bays.
5KM 500kV Transmission Line.
15KM 220kV Transmission Line.</p>

<div class="hr" style="text-align: left;"></div>
<p class="style11" style="text-align: left;"><strong>NTDC-KESC 500/220 kV INTERCONNECTION PROJECT (PHASE-II)</strong></p>
<p class="style11" style="text-align: left;">500/220 kV GIS Grid station along with 500kV IN/OUT and 220kV Transmission Line Feeding KESC Network ??? Residency Construction Supervision Including Contract Administration, Quality Control, Contractors Claim Certification, Safety Programme, Follow Up and Revision Of Construction Schedules, Monitoring and Reporting Of Progress, Variation Orders and Design Changes During Execution, Testing And Commissioning, Final Completion Report And Handing Over The Project.</p>
<p class="style11" style="text-align: left;"><strong>Total Project Cost</strong> <strong>-</strong> PKR 284 Million and US$ 29.3 Million
<strong>Barqaab Share</strong> <strong>-</strong> 100%
<strong>Date of Commencement</strong> <strong>-</strong> October 2004
<strong>Date of Completion -</strong> December 2006</p>
<p class="style11" style="text-align: left;"><strong>SCOPE OF WORK</strong></p>
<p class="style11" style="text-align: left;">Two Nos. 500/220kV 3x200MVA Transformer Bay.
Two Nos. 220kV Line Bays.
Two Nos. 500kV Line Bays.
5KM 500kV Transmission Line.
15KM 220kV Transmission Line.</p>

<div class="hr" style="text-align: left;"></div>
<p class="style11" style="text-align: left;"><strong>500 kV MUZAFFARGARH AND GATTI TRANSMISSION LINE PROJECT</strong></p>
<p class="style11" style="text-align: left;">Residency Construction Supervision Including Contract Administration, Quality Control, Contractors Claim Certification, Safety Programme, Follow Up and Revision of Construction Schedules, Monitoring and Reporting of Progress, Variation Orders and Design Changes During Execution Testing And Commissioning, Final Completion Report And Handing Over the Project.</p>
<p class="style11" style="text-align: left;"><strong>Total Project Cost</strong> <strong>-</strong> US$ 44 Million + PKR 458.9 Million
<strong>Barqaab Share - </strong>100%
<strong>Date of Commencement</strong> <strong>-</strong> November 2005
<strong>Date of Completion</strong> <strong>- </strong>September 2008</p>
<p class="style11" style="text-align: left;"><strong>SCOPE OF WORK</strong></p>
<p class="style11" style="text-align: left;">280km 500 kV Single Circuit, Quad Bundle Transmission Line from Muzzafargarh to Gatti.</p>

<div class="hr" style="text-align: left;"></div>
<p class="style11" style="text-align: left;"><strong>500 kV MUZAFFARGARH AND GATTI GRID STATIONS EXTENSION PROJECT</strong></p>
<p class="style11" style="text-align: left;">Residency Construction Supervision Including Contract Administration, Quality Control, Contractors Claim Certification, Safety Programme, Follow Up and Revision of Construction Schedules, Monitoring and Reporting of Progress, Variation Orders and Design Changes During Execution Testing And Commissioning, Final Completion Report And Handing Over the Project.</p>
