      'title' => 'MANGLA DAM RAISING PROJECT ',
      'slug' => 'mangla-dam-raising-project',
      'category' => 'dams-hydropower',
      'project_category_id' => 3,
      'subtitle' => 'TENDER DOCUMENTATION AND CONSTRUCTION SUPERVISION',
      'body' => '<p style="text-align: left;">Test BARQAAB is providing technical expert services in the Project for the detailed engineering and tender documents in Phase-II, provide experts in bidding and award of construction contacts in phase-III A and also conduct construction supervision in phase-III B. BARQAAB Share is 17%.The Mangla Dam Raising Project involves raising of main and auxiliary dams, modification of the Headwork &amp; orifice of the main spillway and construction of a control weir for the emergency spillway. Mangla Dam is to regain the storage capacity lost due to sedimentation in the reservoir.  The average annual water availability for irrigation releases will increase by 2.88 MAF.  To achieve other benefits like increase in annual energy output by 772 GWh which is equivalent to 150 MW in generating capacity, development of fisheries and increased economic in the area.</p>',
      'scope_of_project' => 'Scope of the Project - BARQAAB is providing technical expert services in the Project for the detailed engineering and tender documents in Phase-II, provide experts in bidding and award of construction contacts in phase-III A and also conduct construction supervision in phase-III B. BARQAAB Share is 17%.The Mangla Dam Raising Project involves raising of main and auxiliary dams, modification of the Headwork & orifice of the main spillway and construction of a control weir for the emergency spillway. Mangla Dam is to regain the storage capacity lost due to sedimentation in the reservoir.  The average annual water availability for irrigation releases will increase by 2.88 MAF.  To achieve other benefits like increase in annual energy output by 772 GWh which is equivalent to 150 MW in generating capacity, development of fisheries and increased economic in the area.',
      'scope_of_services' => 'Scope of the Services - BARQAAB is providing technical expert services in the Project for the detailed engineering and tender documents in Phase-II, provide experts in bidding and award of construction contacts in phase-III A and also conduct construction supervision in phase-III B. BARQAAB Share is 17%.The Mangla Dam Raising Project involves raising of main and auxiliary dams, modification of the Headwork & orifice of the main spillway and construction of a control weir for the emergency spillway. Mangla Dam is to regain the storage capacity lost due to sedimentation in the reservoir.  The average annual water availability for irrigation releases will increase by 2.88 MAF.  To achieve other benefits like increase in annual energy output by 772 GWh which is equivalent to 150 MW in generating capacity, development of fisheries and increased economic in the area.',
      'attributes_data' => '[{"label":"Total Project Cost: ","value":"PKR 62,500 Million."},{"label":"BARQAAB Share:","value":"35%"},{"label":"Date of Commencement: ","value":"August 2002"},{"label":"Date of Completion:","value":" December 2010"}]',
      'status' => 'published',
