    6 => 
    array (
      'id' => 7,
      'wordpress_id' => 4134,
      'title' => 'FEASIBILITY STUDY FOR RAISING OF MANGLA DAM',
      'slug' => 'feasibility-study-for-raising-of-mangla-dam',
      'category' => 'dams-hydropower',
      'project_category_id' => 3,
      'subtitle' => '',
      'body' => '<h1 class="giga">Feasibility Study For Raising <span class="accent">of Mangla Dam</span></h1>





<p style="text-align: left;">BARQAAB provided technical expert services in the study for Hydrology Water availability assessment of sedimentation, reservoir operation, structural design review, environmental and resettlement implications, geo-technical and seismic issues, construction issues and economic feasibility of the Project. It also provided the home office coordination to the joint venture.</p>
<p style="text-align: left;">The storage capacity of Mangla Dam (on river Jhelum) is fastly decreasing due to sedimentation. Mangla Dam has lost 20% of its gross capacity. The objective of the project was to see whether Raising of Mangla Dam is feasible upto the original 40 feet provided in the original design and to choose the optimum level of raising from technical, environmental and resettlement considerations. If it is found feasible, detailed design, Tender Documentation and preparation of RAP shall be undertaken in Phase-II Studies.</p>',
      'scope_of_project' => NULL,
      'scope_of_services' => NULL,
      'attributes_data' => '[{"label":"Total Project Cost","value":"PKR 62,500 Million"},{"label":"BARQAAB Share","value":"33%"},{"label":"Date of Commencement","value":"August 2000"},{"label":"Date of Completion","value":"December 2000"}]',
      'status' => 'published',
      'sort_order' => 5,
      'meta' => '{"original_slug": "feasibility-study-for-raising-of-mangla-dam", "original_url": "http:\\/\\/barqaab.com.pk\\/?post_type=portfolios&#038;p=4134", "category": "dams-hydropower"}',
      'published_at' => '2014-11-18 07:28:43',
      'created_at' => '2026-07-12 10:53:59',
      'updated_at' => '2026-07-15 09:30:43',
    ),
