      'subtitle' => '',
      'body' => '
<h1 class="giga">20MW PUNJNAD <BR>LOW HEAD <BR> <span class="accent"> HYDROPOWER PROJECT</span></h1><h2>( Feasibilty Study)</h2>


<p style="text-align: left;">The Consultancy Services Include supervision of survey and investigation work conducted on the program prepared by Consultants and Carrying out Feasibility Study of the hydropower project and prepare an acceptable and bankable report of the project covering Feasibility level Design and drawings of each structure, Bill of Quantities, Cost estimates, Powerhouse and Power plant, hydro mechanical, electrical and miscellaneous auxiliary equipment (Technical particulars, numbers, capacity etc.), Economic & Financial Analysis, Environmental Impact Assessment, Workout cost per KWh of power production, Prepare and provide the Hydrological, Geotechnical and Topographical Survey Report, Alternative Layouts and Comparison, IEE Social and Resettlement Report and Feasibility Report.</p>

<BR><p style="text-align: left;">The main objective of Punjnad Low Head Hydropower Project is to utilize the flows of River Chenab at Punjnad Barrage to generate 18 MW power and supply into national grid system immediately. The project, falling in the load centre area will be connected to the nearest grid station and thus will contribute to the national grid with minimum line losses and no substantial cost for transmission line.</p>

<BR><p style="text-align: left;">Proposed Punjnad Low Head Hydropower Project will be constructed along the right bank of Punjnad Barrage on Chenab River. The project area is located on the right bank of Punjnad Barrage. The headrace and the powerhouse are at a distance of 608 m away from the centerline of the Barrage. The powerhouse is estimated to have an installed capacity of 18 MW and an annual energy output of 58 GWh at 30% probability time with available head ranging between 2.0 to 5.0 m. The powerhouse including service bay has a length of 75.95 m and width of 49.18 m.  The total length including upstream and downstream concrete floors is 65.97 m. The designed foundation level is fixed at EL 86.22 whereas the top elevation of the powerhouse is at 115.00 m. The headrace comprises trapezoidal cross-section having total length of approximately 840 m and a bed width of 80 m.  The top width is approximately 111.52 m and the average depth is about 4.46 m. The tailrace comprising trapezoidal cross-section has a length of approximately 230 m and a bed width of 96 m.  The top width is 132.04 m.</p>



<p style="padding:50px 0px 50px 0px; border-style: dashed; border-width: 1px; font-weight:bold;">
Date of Commencement: April 2008
Date of Completion: November 2008
',
