      'subtitle' => '',
      'body' => '
<h1 class="giga">GOMAL ZAM DAM</h1><h2>DEVELOPMENT OF DESIGN CONCEPTS AFTER INVESTIGATION</h2>



<p style="text-align: left;">Collection of data, review, formulation of programme for additional survey, evaluation of available and proposed geological mapping of dam and appurtenant structures, preliminary study of rock cut slopes, design of Adit on right abutment for investigation, preparation of tender documents and preparation of studies report on materials.  Development of Design Concepts for diversion during construction and shifting of power house in the body of the dam.</p>
<BR><p style="text-align: left;">Gomal Zam Dam Multipurpose Project located in South Wazirastan, KPK on river Gomal is an RCC Dam with a Barrage at Kot Murtaza.  An irrigation system off-takes from this barrage to feed an area. Of 163,000 Acres in D.I.Khan plain.  The dam has a height of 436 feet and a live storage of 0.892 MAF and a generation capacity of 17.4 MW.  The dam is proposed to be construction on turnkey basis.</p>



<p style="padding:50px 0px 50px 0px; border-style: dashed; border-width: 1px; font-weight:bold;">
Date of Commencement: May 2001.
Date of Completion: August 2001.</p>
',
