<BR><p style="text-align: left;">Development of reservoir on Haro river and Nandana Kas with a 5 miles channel of 32000 cusecs to divert water from Tarbela reservoir a dam 240 ft. High would be constructed to develop irrigated agriculture in the region supplement the existing supplies from the Indus and Hydropower Generation. </p>


