      'body' => '
<h1 class="giga">DHOK PATHAN <span class="accent"> AND AKHORI DAM PROJECTS</span></h1><h2>( Appraisal Study)</h2>



<p style="text-align: left;">Preparation of Feasibility / Appraisal Report of the Project to assess whether the Project is technically feasible, environmentally suitable and socially acceptable. Identification of local land potential for irrigated agriculture and check potential of future development.  Preparation of EIA and Resettlement Report with costing and suggestions of mitigation measures. </p>
<BR><p style="text-align: left;">Development of reservoir (Akhori Dam) on Soan river and Nandana Kas with a 33 Km Channel of 82,000 cusec to divert water from Tarbela reservoir.  A dam of 418 ft. High at Nandana Kas and 190 ft. High at Soan river would be constructed to develop irrigation and supplement to the existing supplies from the Indus and provide Hydropower Generation.</p>


