      'body' => '
<h1 class="giga">IMPLEMENTATION OF INDUS RIVER <span class="accent"> TRIBUTARIES HIGH-HEAD HYDROPOWER COMPLEX</span></h1><h2>( DESIGN REVIEW AND CONSTRUCTION SUPERVISION OF HYDROPOWER PROJECT INCLUDING SWITCHYARD AND GRID STATIONS)</h2>



<p style="text-align: left;">The Consultancy Services include Contractors design review and construction supervision of three High Head Hydropower Projects. The project activities also include design of 2 Nos. bridges over Indus River near Besham in district Hazara, for access to powerhouse site as well as reservoir area. The span of the two bridges is 100 meter and 120 meter respectively. In addition preparation of cost of various components of the project and preparation of PC-1 proforma is to be done.</p>
<BR><p style="text-align: left;">The Project comprises utilising the discharge of tributaries of Indus river near Basham in KPK for Hydropower development namely Khan Khwar, Duber Khwar and Allai Khwar Hydropower Project with installed capacity of 72 MW, 130 MW and 121 MW respectively. Cost of the Project is Khan Khwar Rs. 8,301 million, Duber Khwar Rs. 16,324 million and Allai Khwar Rs. 8,577 million.</p>


<p style="padding:50px 0px 50px 0px; border-style: dashed; border-width: 1px; font-weight:bold;">Total Project Cost: PKR 33,202 Million.
BARQAAB Share: 22%.
Date of Commencement: November 2002.
Date of Completion: October 2010.</p>
',
