      'title' => 'UPGRADATION AND RELOCATION OF KARAKORUM HIGHWAY FOR BASHA DAM PROJECT',
      'slug' => 'upgradation-and-relocation-of-karakorum-highway-for-basha-dam-project',
      'category' => 'construction-highways',
      'project_category_id' => 2,
      'subtitle' => '',
      'body' => '
<h1 class="giga">UPGRADATION AND RELOCATION <span class="accent"><BR> OF KARAKORUM HIGHWAY</span></h1>
<h2> FOR BASHA DAM PROJECT </h2>


<p style="text-align: left;">BARQAAB provides technical services in the Project for Assessment of Sedimentation, Structure Design Review, Geological Investigations and Conducting Feasibility of the Project along with other numbers of the JV to accomplish the task of upgradation and relocation of Karakoram Highway (KKH) for ascertaining the feasibility of Basha Dam Project.</p>

<BR><p style="text-align: left;">The existing Karakorum Highway N-35 normally called KKH is one of the important road of entire communication network of northern areas of Pakistan which provide surface link to China.  The road 810-km in length starts from Hasanabdal on G. T. Road and Terminates at Khunjrab pass on Pakistan.  China border after passing through Karakorum mountainous range.</p>

<BR><p style="text-align: left;">Construction of Basha Diamer Dam on Indus is one of the Project, envisaged by WAPDA to boost its water resources. The KKH project entailing up-gradation of 371-km to cater for transportation of construction material and heavy machinery during construction and relocation of about 140-km of the existing KKH that will get submerged  consequent upon to the construction of the Dam.</p>


<p style="padding:50px 0px 50px 0px; border-style: dashed; border-width: 1px; font-weight:bold;">
Date of Commencement: December 2002.
Date of Completion: June 2004.</p>
',
