    35 => 
    array (
      'id' => 36,
      'wordpress_id' => 4384,
      'title' => 'RAINEE CANAL PROJECT',
      'slug' => 'rainee-canal-project',
      'category' => 'canals-barrages-drains',
      'project_category_id' => 1,
      'subtitle' => '',
      'body' => '<h1 class="giga">RAINEE CANAL PROJECT</h1>
<h2 class="accent">DETAILED ENGINEERING DESIGN, TENDER DOCUMENTATION AND CONSTRUCTION SUPERVISION</h2>





<p style="text-align: left;">BARQAAB is independently providing the above Consultancy Services for Rainee Canal Project of discharge of 10,000 cusecs. It involves Guddu Barrage Works of extension of Left Divide Wall, River Training Works with one J-Spur on right bank of the river upstream and Canal Head Regulator etc. Main Canal, Branch Canals and Distributaries have number of Structures. Model Studies were also conducted for the major structures.</p>
&nbsp;
<p style="text-align: left;">The services included preparation of detailed design, Engineer???s estimate, Tender Documents, Evaluation of Tenders and Construction Supervision of Rainee Canal. The work also involves assistance in model studies of head regulators and geotechnical investigations of structures. Work comprises of Construction of 10,000 cusecs Head Regulator, Silt Excluder and Skimming Platform on Indus river for Rainee Canal, Construction of Spur on Indus river at Guddu Barrage and Construction of 5 Nos. Cross-Regulators and Complex Structures.</p>
&nbsp;
<p style="text-align: left;">The services included preparation of detailed design, Engineer???s estimate, Tender Documents, Evaluation of Tenders and Construction Supervision of Rainee Canal. The work also involves assistance in model studies of head regulators and geotechnical investigations of structures. Work comprises of Construction of 10,000 cusecs Head Regulator, Silt Excluder and Skimming Platform on Indus river for Rainee Canal, Construction of Spur on Indus river at Guddu Barrage and Construction of 5 Nos. Cross-Regulators and Complex Structures.</p>',
      'scope_of_project' => NULL,
      'scope_of_services' => NULL,
      'attributes_data' => NULL,
      'status' => 'published',
      'sort_order' => 34,
      'meta' => '{"original_slug": "rainee-canal-project", "original_url": "http:\\/\\/barqaab.com.pk\\/?post_type=portfolios&#038;p=4384", "category": "canals-barrages-drains"}',
      'published_at' => '2014-11-20 09:26:37',
      'created_at' => '2026-07-12 10:53:59',
      'updated_at' => '2026-07-15 09:30:43',
    ),
    36 => 
    array (
      'id' => 37,
      'wordpress_id' => 4387,
      'title' => 'KACHHI CANAL PROJECT',
      'slug' => 'kachhi-canal-project',
      'category' => 'canals-barrages-drains',
      'project_category_id' => 1,
      'subtitle' => '',
      'body' => '<h1 class="giga">KACHHI CANAL PROJECT</h1>
<h2 class="accent">DETAILED ENGINEERING DESIGN, TENDER DOCUMENTS AND PERFORMANCE EVALUATION OF HILL TORRENT MANAGEMENT AND CONSTRUCTION SUPERVISION</h2>





<p style="text-align: left;">BARQAAB provided technical expert services in the Project for review of Model Studies, preparation of RAP and sociological studies, Detailed Engineering Design, Cost Estimation and Preparation of Tender Documents. And Construction Supervision. In addition the Consultant will carryout the drainage studies and Design and submit a hill torrent management plan. </p>
<p style="text-align: left;">Balochistan is the largest province of the country.  Large tracts of fertile and fairly levelled land are available for cultivation in Kachhi Plain.  The Kachhi Canal Project envisaged, irrigation of over 713,000 acres of land.  The off-take of the canal from Taunsa Barrage at Indus in Punjab province. The total length of main canal is 500-km in which 300-km in Punjab and 200-km used channel in Balochistan province.  Length of the distributaries and minors is 2000-km and the discharge capacity of the canal is 7,000 cusecs. 64 No. Cross-drainage structure, 83 No. V.R. Bridge and 5 No. A.R. Bridges are proposed to be constructed.  The consortium comprises carrying out Detailed Design, preparation of Tender Document, tender evaluation and Construction Supervision of all works. In addition the Consultant will carryout the drainage studies and Design and submit a hill torrent management plan. </p>


<p style="padding:50px 0px 50px 0px; border-style: dashed; border-width: 1px; font-weight:bold;">Total Project Cost: PKR 31,204 Million.
BARQAAB Share: 100%.
Date of Commencement: December 2003.
Date of Completion: June 2010.</p>',
      'scope_of_project' => NULL,
