    37 => 
    array (
      'id' => 38,
      'wordpress_id' => 4389,
      'title' => 'CHASHMA RIGHT BANK CANAL',
      'slug' => 'chashma-right-bank-canal',
      'category' => 'canals-barrages-drains',
      'project_category_id' => 1,
      'subtitle' => '',
      'body' => '
<h1 class="giga">CHASHMA <BR> RIGHT BANK CANAL <BR><span class="accent"> (LIFT CUM GRAVITY) PROJECT</span></h1>
<h2>DETAILED DESIGN AND TENDER DOCUMENTS</BR>





<p style="text-align: left;">BARQAAB provided technical services in the Project for Planning, Detailed Hydraulic and Structural Design, Environmental Impact Assessment, Resettlement Action Plan, Geological Investigations, Model Studies Supervision. </p>
<BR><p style="text-align: left;">The Project of CRBC (Lift cum Gravity) canal envisages irrigation of over 286,000 acres of land in D. I. Khan District, contiguous with right bank of existing CRBC Gravity System, through a lift cum gravity canal off-taking from Indus river at Chashma Barrage.  Project comprises a new intake structure with design discharge of 2,613 cusecs a feeder canal of about 39-km length.  Main Canal of about 73-km length 25 Nos. Distributaries of 167-km length and 24 No. Minors of 102 canal miles length on farm developments of proposed command area through watercourses and flood protection and drainage works are also proposed.</p>


<p style="padding:50px 0px 50px 0px; border-style: dashed; border-width: 1px; font-weight:bold;">Total Project Cost: PKR 158,45 Million.
BARQAAB Share: 100%.
Date of Commencement: June 2002.
Date of Completion: January 2004.</p>
',
      'scope_of_project' => NULL,
      'scope_of_services' => NULL,
      'attributes_data' => NULL,
      'status' => 'published',
      'sort_order' => 36,
      'meta' => '{"original_slug": "chashma-right-bank-canal", "original_url": "http:\\/\\/barqaab.com.pk\\/?post_type=portfolios&#038;p=4389", "category": "canals-barrages-drains"}',
