<p style="text-align: left;">BARQAAB provided Consultancy Services as a Joint Venture for Feasibility Studies, Detailed Design, Tender Documents and Construction Supervision of RBOD-III in Sindh Province.</p>
<BR><p style="text-align: left;">The Services consist of carrying out feasibility studies of Shahdad Kot Unit, preparation of Detailed Design, Tender Documents, Tender Evaluation and Construction Supervision of drainage works. </p>
<BR><p style="text-align: left;">The Project is located in Sindh and comprises feasibility studies, Detailed Engineering Design and Construction Supervision of Shahdad Kot unit drainage disposal of Balochistan, MNV Drain, Carrier Drain and other drains of Indus Right Bank to ultimately outfall into the Indus Link and Indus River.</p>



