      'title' => 'LINING OF ROHRI CANAL, DADU CANAL AND RICE CANAL',
      'slug' => 'lining-of-rohri-canal-dadu-canal-and-rice-canal',
      'category' => 'canals-barrages-drains',
      'project_category_id' => 1,
      'subtitle' => '',
      'body' => '
<h1 class="giga">LINING OF ROHRI CANAL<span class="accent"> <BR>DADU CANAL <BR>AND RICE CANAL</span></h1>
<h2>FEASIBILITY STUDY, DETAILED ENGINEERING DESIGN, TENDER DOCUMENTS AND PC-I</h2>


<p style="text-align: left;">BARQABB provided services for Feasibility Study, Detailed Engineering Design, Tender Documents and PC-I of Rohri, Dadu and Rice Canals with a Joint Venture with ACE.</p>
<BR><p style="text-align: left;">Carry out Condition Survey of all the three canals, establish their existing status of herms and prism, inventory of structures, settlements around the canal alignment, Geo-Tech investigations. The project studies included Lining methods under canal flow conditions, selection of Lining options and preparation of cost estimates, environmental and Socio-economic studies etc and process a general consensus to develop Pilot project for Technically feasible and economically viable Lining options.</p>
<BR><p style="text-align: left;">BARQAAB provided Services in Hydraulics and Structural Design Economic and Socio-Economic studies, Surveys through GIS, Costing and other design related fields.</p>



<p style="padding:50px 0px 50px 0px; border-style: dashed; border-width: 1px; font-weight:bold;">Total Project Cost: PKR 85 Million.
BARQAAB Share: 25%.
Date of Commencement: July 2009.
Date of Completion: March 2010.</p>
',
