      'meta' => '{"original_slug": "lining-of-rohri-canal-dadu-canal-and-rice-canal", "original_url": "http:\\/\\/barqaab.com.pk\\/?post_type=portfolios&#038;p=4397", "category": "canals-barrages-drains"}',
