    43 => 
    array (
      'id' => 44,
      'wordpress_id' => 4398,
      'title' => 'CANAL SYSTEM OF LBDCIP-PACKAGE-5',
      'slug' => 'canal-system-of-lbdcip-package-5',
      'category' => 'canals-barrages-drains',
      'project_category_id' => 1,
      'subtitle' => '',
      'body' => '
<h1 class="giga">INSTITUTIONAL STRENGTHENING,<span class="accent"> <BR>CAPACITY BUILDING AND<BR>IMPROVED OPERATION MANAGEMENT</span></h1>
<h2>OF THE CANAL SYSTEM OF LBDCIP-PACKAGE-5</h2>


<p style="text-align: left;">Study both the existing irrigation operation and irrigation management in the Project Area and those in LCC command where management transfer has commenced. Review of procedures for information of KPs??? and FOs, highlight deficiencies and suggest improvements. Review of strategies/polices initiated by PIDA for participation of water user in irrigation management laws/rules framed by PIDA for opreationalization of FO???s, their effectiveness and highlight weaknesses along with suggestion for improvement. Carry out awareness raising, educating rights, and Management skills development.</p>
<BR><p style="text-align: left;"Strengthening and Capacity Building  of Farmers Organization (FO) and Area Water Boards (AWB), Provide Training, Training of Trainers, Management Development, Abiana Assessment , Financial Management, Irrigation Management.</p>
<BR><p style="text-align: left;">BARQAAB provided services for this ADB funded Project as a joint venture partner of 25% share. The project aims at Institutional reforms, formation of AWBs and FOs and then effective working Capacity Building and training.</p>



<p style="padding:50px 0px 50px 0px; border-style: dashed; border-width: 1px; font-weight:bold;">Total Project Cost: 14,700 Million.
BARQAAB Share: 25%.
Date of Commencement: February 2010.
Date of Completion: January 2014.</p>
',
